Method.Source:
    /// <summary>
    /// Filter vendor lookup with AllowChargeThrough = Yes OR AllowCrossDock = Yes
    /// when called from the charge through invoice screen
    /// </summary>
    void init()
    {
        QueryBuildRange queryBuildRange;
        
        next init();

        Args args = this.args();

        if (args.caller().name() == formStr(METCBCTInvoiceForm))
        {
            Query q = this.VendTable_q;
            QueryBuildDataSource qbds = q.dataSourceTable(tableNum(VendTable));

            QueryBuildDataSource qbdsMETVendTable = qbds.addDataSource(tableNum(METVendTable));
            qbdsMETVendTable.joinMode(joinMode::InnerJoin);
            qbdsMETVendTable.relations(true);

            queryBuildRange = qbdsMETVendTable.addRange(fieldNum(METVendTable, AllowChargeThrough));
            queryBuildRange.value(strFmt('((%1 == %2) || (%3 == %2))', fieldStr(METVendTable, AllowChargeThrough), any2int(NoYes::Yes), fieldStr(METVendTable, AllowCrossDock)));

        }
    }
